package mage.player.ai;
import mage.Mana;import mage.abilities.*;import mage.abilities.costs.Cost;import mage.abilities.costs.common.ExileFromGraveCost;import mage.cards.Card;import mage.constants.*;import mage.game.permanent.Permanent;import mage.target.Target;import java.util.*;
import static mage.player.ai.FourthSeatRealGameTest.check;import static mage.player.ai.RecoveryChecks.*;
/** Reconstructed regression contracts; historical results are not evidence for this source. */
public final class FourthSeatRecoveredCostsTest {
 static Target exile(Ability a){for(Cost c:a.getCosts())if(c instanceof ExileFromGraveCost)return c.getTargets().get(0);throw new AssertionError("Missing grave exile cost");}
 static Ability normalize(Ability a)throws Exception{java.lang.reflect.Method m=ComputerPlayerFourthSeat.class.getDeclaredMethod("normalizePartialGraveExileCosts",Ability.class);m.setAccessible(true);return (Ability)m.invoke(null,a);}
 public static void main(String[]args)throws Exception{
  for(int n:new int[]{4,5,6})run("Uro actual escape other grave count="+n,()->{FourthSeatRealGameTest.Fixture f=fixture("a.AesiTyrantOfGyreStrait","Aesi, Tyrant of Gyre Strait");Card uro=f.card("u.UroTitanOfNaturesWrath","Uro, Titan of Nature's Wrath");grave(f,uro);List<Card> others=new ArrayList<>();for(int i=0;i<n;i++){Card c=f.card("basiclands.Forest","Forest");grave(f,c);others.add(c);}ActivatedAbility escape=(ActivatedAbility)uro.getAbilities().stream().filter(a->a instanceof mage.abilities.keyword.EscapeAbility).findFirst().get();f.bot.getManaPool().addMana(new Mana(0,2,0,0,2,0,0,0),f.game,escape);library(f,5);if(n==4){check(!fund(f,escape),"Insufficient exile cards admitted");reject(f,uro);}else{cast(f,uro,1);check(others.stream().filter(c->f.game.getState().getZone(c.getId())==Zone.EXILED).count()==5,"Did not exile exactly five other cards");check(f.bot.getManaPool().getMana().count()==0,"Escape GGUU unpaid");drain(f,10);check(f.game.getPermanent(uro.getId())!=null,"Escaped Uro sacrificed itself");}});
  for(boolean complete:new boolean[]{false,true})run("Escape normalization copy preserves complete="+complete,()->{FourthSeatRealGameTest.Fixture f=fixture("a.AesiTyrantOfGyreStrait","Aesi, Tyrant of Gyre Strait");Card u=f.card("u.UroTitanOfNaturesWrath","Uro, Titan of Nature's Wrath");grave(f,u);Ability a=u.getAbilities().stream().filter(x->x instanceof mage.abilities.keyword.EscapeAbility).findFirst().get().copy();for(int i=0;i<5;i++){Card c=f.card("basiclands.Forest","Forest");grave(f,c);if(complete||i==0)exile(a).addTarget(c.getId(),a,f.game);}List<UUID> ids=new ArrayList<>(exile(a).getTargets());Ability copy=normalize(a);check(copy!=a&&exile(a).getTargets().equals(ids),"Original selection mutated");check(exile(copy).getTargets().size()==(complete?5:0),"Copied choice normalization wrong");exile(copy).clearChosen();check(exile(a).getTargets().equals(ids),"Copy aliases original");check(f.bot.getGraveyard().size()==6,"Normalization mutated grave");});
  for(String mode:new String[]{"grave","hand","no-mana","no-discard","life2","stale-hand","stale-unfunded"})run("Demonic Embrace dynamic conjunction "+mode,()->{FourthSeatRealGameTest.Fixture f=fixture("l.LathrilBladeOfTheElves","Lathril, Blade of the Elves");Permanent target=f.board("w.WirewoodSymbiote","Wirewood Symbiote");Card c=f.hand("d.DemonicEmbrace","Demonic Embrace");boolean hand=mode.equals("hand")||mode.startsWith("stale");if(!mode.equals("hand"))c.moveToZone(Zone.GRAVEYARD,null,f.game,false);if(mode.startsWith("stale")){c.getSpellAbility().canActivate(f.bot.getId(),f.game);check(f.bot.getCastSourceIdWithAlternateMana().containsKey(c.getId()),"Stale registration not established");c.moveToZone(Zone.HAND,null,f.game,false);}Card spare=(!hand&&!mode.equals("no-discard"))?f.hand("g.GrizzlyBears","Grizzly Bears"):null;boolean mana=!mode.equals("no-mana")&&!mode.equals("stale-unfunded");if(mana){f.bot.getManaPool().addMana(Mana.BlackMana(2),f.game,c.getSpellAbility());f.bot.getManaPool().addMana(Mana.ColorlessMana(1),f.game,c.getSpellAbility());}if(mode.equals("life2"))f.bot.setLife(2,f.game,null);f.game.applyEffects();ActivatedAbility a=c.getSpellAbility().copy();a.getTargets().get(0).addTarget(target.getId(),a,f.game);boolean valid=mode.equals("grave")||mode.equals("hand")||mode.equals("stale-hand");int costCount=c.getSpellAbility().getCosts().size();String registrations=f.bot.getCastSourceIdWithAlternateMana().toString();for(int i=0;i<2;i++)check(fund(f,a)==valid,"Wrong dynamic affordability");check(c.getSpellAbility().getCosts().size()==costCount&&c.getSpellAbility().getTargets().get(0).getTargets().isEmpty(),"Live ability mutated");check(f.bot.getCastSourceIdWithAlternateMana().toString().equals(registrations),"Live registrations mutated");if(!valid){reject(f,c);check(f.bot.getLife()==(mode.equals("life2")?2:40),"Rejected action paid life");}else{cast(f,c,1);check(f.bot.getLife()==(hand?40:37),"Wrong life surcharge");check(f.bot.getManaPool().getMana().count()==0,"1BB unpaid");if(!hand)check(f.game.getState().getZone(spare.getId())==Zone.GRAVEYARD,"Discard unpaid");drain(f,10);Permanent aura=f.game.getPermanent(c.getId());check(aura!=null&&target.getId().equals(aura.getAttachedTo()),"Aura failed attachment");}});
  for(String spare:new String[]{"none","nonred","red"})for(int mana:new int[]{0,5,6})run("Pyrokinesis source exclusion spare="+spare+" mana="+mana,()->{FourthSeatRealGameTest.Fixture f=fixture("t.TorbranThaneOfRedFell","Torbran, Thane of Red Fell");List<Permanent> targets=new ArrayList<>();for(int i=0;i<4;i++)targets.add(f.enemyBoard(i%3,"c.CentaurCourser","Centaur Courser"));Card c=f.hand("p.Pyrokinesis","Pyrokinesis"),other=spare.equals("none")?null:f.hand(spare.equals("red")?"g.GoblinArsonist":"basiclands.Forest",spare.equals("red")?"Goblin Arsonist":"Forest");if(mana>0)f.bot.getManaPool().addMana(Mana.RedMana(mana),f.game,c.getSpellAbility());boolean payable=mana==6||spare.equals("red");if(!payable){check(!fund(f,c.getSpellAbility()),"Self-exile alternative admitted");reject(f,c);}else{cast(f,c,2);Ability chosen=f.game.getStack().peek().getStackAbility();int amount=0;for(UUID id:chosen.getTargets().get(0).getTargets())amount+=chosen.getTargets().get(0).getTargetAmount(id);check(amount==4&&chosen.getTargets().get(0).getTargets().size()==4,"Divided amount/targets changed");if(mana<6)check(f.game.getState().getZone(other.getId())==Zone.EXILED,"Real spare red exile unpaid");drain(f,10);}});
  finish("RECOVERED_COSTS");
 }
}
